"""Turn the buyer guide into a useful, private first-call companion."""
import shutil


def add(out, origin, pages):
    why='''<section class="wrap why-local" aria-labelledby="why-local-title"><div class="why-local-intro"><div class="eyebrow">WHY CHOOSE A WAZOOZIE CONNECTION?</div><h2 id="why-local-title">Good reputations deserve<br><em>a bigger stage.</em></h2><p>Small businesses. Skilled people. Local affiliates with a name to stand behind. Wazoozie helps you get past the pitch and start a better conversation.</p></div><div class="why-local-grid"><article><span>01 / KNOW THE NAME</span><h3>Meet a business.<br>Skip the mystery.</h3><p>See the named business or professional before deciding who to contact. Your next step stays your choice.</p><a href="/local-help/">Explore the local shortlist →</a></article><article><span>02 / READ THE CONTEXT</span><h3>A recommendation<br>with a reason.</h3><p>Read the listing’s evidence and relationship disclosures. New owner-recommended profiles link public sources and explain what has not been independently checked.</p><a href="/our-standards/">See how listings work →</a></article><article><span>03 / TALK TO THE PEOPLE</span><h3>Less runaround.<br>A clearer first call.</h3><p>Use the direct contact details, bring your questions and agree on scope and pricing with the business doing the work.</p><a href="/before-you-say-yes/">Take the better questions →</a></article></div></section>'''
    home=out/'index.html';s=home.read_text();marker='<section class="concierge-home wrap grand-finder"';assert marker in s
    home.write_text(s.replace(marker,why+marker,1))
    decoder='''<section id="offer-decoder" class="offer-decoder" aria-labelledby="offer-decoder-title"><div class="decoder-intro"><div class="eyebrow">THE HEADLINE IS JUST THE OPENING LINE.</div><h2 id="offer-decoder-title">Is that really<br><em>a $49 visit?</em></h2><p>Put the pieces of a service-call offer together before you book. Use the business’s confirmed charges for the same visit. Don’t count a diagnostic fee twice if it is already included.</p><p>Unknown is not zero. Enter <strong>0 only when the business confirms there is no additional charge</strong>. Include required fees and applicable taxes in the last field. This tool adds your inputs; it does not verify an offer or estimate repairs.</p><p><a href="/before-you-say-yes/#fine-print-theater">Enjoy the rest of Fine Print Theater →</a></p></div><div class="decoder-workspace"><form id="offer-form" hidden novalidate><fieldset><legend>What would I owe before approving repairs?</legend><label for="offer-visit">Advertised visit / dispatch charge ($)</label><input id="offer-visit" name="visit" type="text" inputmode="decimal" maxlength="12" placeholder="Ask the business" autocomplete="off"><label for="offer-diagnostic">Additional diagnostic charge, if separate ($)</label><input id="offer-diagnostic" name="diagnostic" type="text" inputmode="decimal" maxlength="12" placeholder="Unknown? Leave blank" autocomplete="off"><label for="offer-extras">Other required charges and taxes ($)</label><input id="offer-extras" name="extras" type="text" inputmode="decimal" maxlength="12" placeholder="Enter 0 only if confirmed" autocomplete="off"></fieldset><div class="decoder-actions"><button class="btn primary" type="submit">See the whole visit →</button><button class="btn outline" type="reset">Clear</button></div><button class="decoder-example" id="offer-example" type="button">Try a fictional $49 + $150 example</button><p id="offer-result" role="status" aria-live="polite">Enter all three confirmed amounts. Blank fields mean the total is still unknown.</p><details id="offer-notes-panel" hidden><summary>Your first-call notes · open to review or copy</summary><label for="offer-notes">Review your notes</label><textarea id="offer-notes" rows="8" readonly placeholder="Your result and questions will appear here."></textarea><button class="btn outline" id="offer-copy" type="button" disabled>Copy my call notes</button><p id="offer-copy-status" role="status" aria-live="polite"></p></details><small>Calculated in this page. Entries are not saved or sent. Copying happens only when you choose it.</small></form><noscript><p>Add the advertised visit charge + any separate diagnostic charge + other required charges and applicable taxes. Ask which fees are credited only if you approve repairs. A blank or unknown charge means you cannot yet calculate the total.</p></noscript></div></section>'''
    for path in ('pricing-guide','before-you-say-yes'):
        target=out/path/'index.html';s=target.read_text()
        marker='<section id="hvac"' if path=='pricing-guide' else '<nav class="buying-jumps"'
        assert marker in s;s=s.replace(marker,decoder+marker,1)
        s=s.replace('</body>','<script type="module" src="/assets/offer-decoder.js"></script></body>')
        if path=='pricing-guide':s=s.replace('aria-label="Price guide sections">','aria-label="Price guide sections"><a href="#offer-decoder">Decode a service-call offer</a>',1)
        target.write_text(s)
    for path in (out/'index.html',out/'pricing-guide/index.html',out/'before-you-say-yes/index.html'):
        path.write_text(path.read_text().replace('</head>','<link rel="stylesheet" href="/assets/buyer-edge.css"></head>',1))
    for asset in ('buyer-edge.css','offer-decoder.js'):
        shutil.copy(out.parent/'assets'/asset,out/'assets'/asset)
